// Acessa o campo output do primeiro item do array de entrada
let str = items[0].json.output;

// Função para tratar o texto
function processText(output) {
    // Remover texto entre 【】
    return output.replace(/【.*?】/g, '');
}

// Verifica se str está vazio
if (str && str.length > 0) {
    // Processa o texto se str não estiver vazio
    str = processText(str);
    retorno = { "output": str }; // Retorna o texto processado
} else {
    retorno = true; // Retorna true se str estiver vazio
}

// Retorna o resultado processado
return [{ json: { resultado: retorno } }];

