={{(() => {
  // Obtém o nome do sender
  const name = $('Webhook').item.json.body.messages[0].sender.name || '';
  // Separa em palavras, capitaliza cada uma e retorna o nome formatado
  return name
    .split(' ')
    .filter(w => w) // Remove espaços extras
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
})()}}

